import { stripNumericPrefix, parseFrontMatter } from './vault-graph.mjs';

const COMMUNITY_TONES = ['teal', 'blue', 'purple', 'amber', 'emerald', 'rose', 'indigo', 'slate'];

export function formatConciseGraphTitle(raw = '', maxLen = 10) {
  let text = String(raw || '').trim();
  if (!text) return '未命名';
  if (text.includes('/')) text = text.split('/').pop() || text;
  text = text.replace(/\.(md|markdown)$/i, '');
  // Strip trailing UUIDs or timestamp-UUID suffixes generated by memos/whiteboards
  text = text.replace(/[\s_-]+[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i, '');
  text = text.replace(/\s+\d{4}-\d{2}-\d{2}\s+\d{6}-[0-9a-f-]+$/i, '');
  text = stripNumericPrefix(text);
  text = text.replace(/^\d+(?:\.\d+)*[\s·._-]+/, '').trim();
  if (/^[0-9a-f]{6,12}(?:-[0-9a-f]+)+$/i.test(text)) {
    return '速记卡片';
  }
  if (text.length > maxLen) {
    text = text.slice(0, maxLen).replace(/[、，,·\-_\s（(：:]+$/, '');
  }
  return text || '笔记';
}

/**
 * CANVAS-001 & CANVAS-004: Bidirectional BFS Shortest Path & Explainable Cognitive Path on Knowledge Graph
 */
export function findShortestGraphPath(nodes = [], edges = [], startId = '', endId = '', options = {}) {
  const nodeMap = new Map();
  for (const node of nodes || []) {
    if (node && node.id) nodeMap.set(node.id, node);
  }
  if (!startId || !endId || !nodeMap.has(startId) || !nodeMap.has(endId)) {
    return {
      found: false,
      hops: 0,
      nodeIds: [],
      edgeIds: [],
      steps: [],
      hopTransitions: [],
      summary: '请选择有效的起点笔记与终点笔记',
    };
  }
  if (startId === endId) {
    const single = nodeMap.get(startId);
    const label = stripNumericPrefix(single.cleanTitle || single.title || single.label || single.id);
    return {
      found: true,
      hops: 0,
      nodeIds: [startId],
      edgeIds: [],
      steps: [{ id: startId, title: single.title || label, cleanTitle: label, role: 'start' }],
      hopTransitions: [],
      summary: `起点与终点相同：《${label}》（0 跳）`,
    };
  }

  const inferredEdges = Array.isArray(options?.inferredEdges) ? options.inferredEdges : [];
  const allEdges = options?.includeInferred ? [...(edges || []), ...inferredEdges] : [...(edges || [])];
  const edgeById = new Map();

  // Build adjacency list (undirected traversal over links so any connected path is found)
  const adj = new Map();
  for (const id of nodeMap.keys()) adj.set(id, []);
  for (const edge of allEdges) {
    if (!edge || !nodeMap.has(edge.source) || !nodeMap.has(edge.target) || edge.source === edge.target) continue;
    const edgeId = edge.id || `${edge.source}->${edge.target}`;
    if (!edgeById.has(edgeId)) edgeById.set(edgeId, edge);
    adj.get(edge.source).push({ neighbor: edge.target, edgeId, direction: 'forward', edge });
    adj.get(edge.target).push({ neighbor: edge.source, edgeId, direction: 'reverse', edge });
  }

  // Deterministic BFS from startId to endId
  const queue = [startId];
  const visited = new Set([startId]);
  const parentMap = new Map();

  let found = false;
  while (queue.length > 0) {
    const curr = queue.shift();
    if (curr === endId) {
      found = true;
      break;
    }
    const neighbors = adj.get(curr) || [];
    for (const item of neighbors) {
      if (!visited.has(item.neighbor)) {
        visited.add(item.neighbor);
        parentMap.set(item.neighbor, { prevId: curr, edgeId: item.edgeId, direction: item.direction, edge: item.edge });
        queue.push(item.neighbor);
      }
    }
  }

  if (!found) {
    const sNode = nodeMap.get(startId);
    const eNode = nodeMap.get(endId);
    const sName = stripNumericPrefix(sNode?.cleanTitle || sNode?.title || startId);
    const eName = stripNumericPrefix(eNode?.cleanTitle || eNode?.title || endId);
    return {
      found: false,
      hops: 0,
      nodeIds: [],
      edgeIds: [],
      steps: [],
      hopTransitions: [],
      summary: `《${sName}》与《${eName}》处于不同连通分量，暂无双链传导路径`,
    };
  }

  const nodeIds = [];
  const edgeIds = [];
  const rawSteps = [];
  let cursor = endId;
  while (cursor) {
    nodeIds.push(cursor);
    const step = parentMap.get(cursor);
    if (!step) break;
    edgeIds.push(step.edgeId);
    rawSteps.push({ fromId: step.prevId, toId: cursor, edgeId: step.edgeId, direction: step.direction, edge: step.edge });
    cursor = step.prevId;
  }
  nodeIds.reverse();
  edgeIds.reverse();
  rawSteps.reverse();

  const steps = nodeIds.map((id, idx) => {
    const n = nodeMap.get(id);
    const cleanTitle = stripNumericPrefix(n?.cleanTitle || n?.title || n?.label || id);
    return {
      id,
      title: n?.title || cleanTitle,
      cleanTitle,
      ghost: Boolean(n?.ghost),
      role: idx === 0 ? 'start' : idx === nodeIds.length - 1 ? 'end' : 'bridge',
    };
  });

  const hopTransitions = rawSteps.map((hop, idx) => {
    const fromNode = nodeMap.get(hop.fromId);
    const toNode = nodeMap.get(hop.toId);
    const fromTitle = stripNumericPrefix(fromNode?.cleanTitle || fromNode?.title || fromNode?.label || hop.fromId);
    const toTitle = stripNumericPrefix(toNode?.cleanTitle || toNode?.title || toNode?.label || hop.toId);
    const edgeObj = hop.edge || edgeById.get(hop.edgeId) || {};
    const confidence = edgeObj.confidence || (edgeObj.kind === 'tag' ? 'INFERRED' : 'EXTRACTED');
    const ev = Array.isArray(edgeObj.evidence) && edgeObj.evidence.length ? edgeObj.evidence[0] : null;
    const defaultSourceNode = hop.direction === 'forward' ? fromNode : toNode;
    const sourceId = ev?.sourceId || defaultSourceNode?.id || hop.fromId;
    const sourcePath = ev?.sourcePath || defaultSourceNode?.relativePath || '';
    const line = ev?.line ?? null;
    const trophicFrom = fromNode?.trophicLayer || 'L1';
    const trophicTo = toNode?.trophicLayer || 'L1';
    const hFrom = fromNode?.trophicHeight ?? 1.2;
    const hTo = toNode?.trophicHeight ?? 1.2;
    let relationLabel = hop.direction === 'forward' ? '显式引用 →' : '← 反向被引用';
    if (confidence !== 'EXTRACTED') {
      relationLabel = edgeObj.reason || (edgeObj.sharedEntities?.length ? `概念实体共现：${edgeObj.sharedEntities.join('、')}` : edgeObj.sharedTags?.length ? `共同标签：#${edgeObj.sharedTags.join(' #')}` : '推断关联');
    }
    return {
      stepIndex: idx + 1,
      edgeId: hop.edgeId,
      fromId: hop.fromId,
      toId: hop.toId,
      fromTitle,
      toTitle,
      direction: hop.direction,
      confidence,
      relation: edgeObj.relation || (confidence === 'EXTRACTED' ? 'references' : 'inferred'),
      relationLabel,
      sourceId,
      sourcePath,
      line,
      trophicFrom,
      trophicTo,
      trophicTransition: `${trophicFrom} (h=${hFrom}) → ${trophicTo} (h=${hTo})`,
    };
  });

  const hops = Math.max(0, nodeIds.length - 1);
  const bridgeCount = Math.max(0, nodeIds.length - 2);
  const chainText = steps.map(s => `《${s.cleanTitle}》`).join(' → ');
  return {
    found: true,
    hops,
    bridgeCount,
    nodeIds,
    edgeIds,
    steps,
    hopTransitions,
    summary: `最短路径 ${hops} 跳（途经 ${bridgeCount} 篇桥梁笔记）：${chainText}`,
  };
}

/**
 * CANVAS-002: PageRank Hub Authority & Community Cluster Detection
 */
export function computeGraphAnalytics(nodes = [], edges = [], options = {}) {
  const validNodes = (nodes || []).filter(n => n && n.id);
  const N = validNodes.length;
  if (N === 0) {
    return {
      pageRankById: new Map(),
      communityById: new Map(),
      communities: [],
      topHubs: [],
      bridgeNodeIds: [],
    };
  }

  const damping = Number(options.damping) || 0.85;
  const iterations = Number(options.iterations) || 28;
  const indexById = new Map(validNodes.map((n, i) => [n.id, i]));

  const outLinks = Array.from({ length: N }, () => []);
  const undirectedAdj = Array.from({ length: N }, () => new Set());
  for (const edge of edges || []) {
    const u = indexById.get(edge?.source);
    const v = indexById.get(edge?.target);
    if (u === undefined || v === undefined || u === v) continue;
    outLinks[u].push(v);
    undirectedAdj[u].add(v);
    undirectedAdj[v].add(u);
  }

  // 1. Power-iteration PageRank
  let ranks = new Float64Array(N).fill(1 / N);
  const nextRanks = new Float64Array(N);
  const baseTeleport = (1 - damping) / N;

  for (let iter = 0; iter < iterations; iter++) {
    let danglingSum = 0;
    for (let i = 0; i < N; i++) {
      if (outLinks[i].length === 0) danglingSum += ranks[i];
    }
    const danglingShare = (damping * danglingSum) / N;
    nextRanks.fill(baseTeleport + danglingShare);
    for (let u = 0; u < N; u++) {
      const outs = outLinks[u];
      if (!outs.length) continue;
      const contrib = (damping * ranks[u]) / outs.length;
      for (const v of outs) nextRanks[v] += contrib;
    }
    ranks.set(nextRanks);
  }

  const maxRank = Math.max(...ranks, 1e-9);
  const pageRankById = new Map();
  for (let i = 0; i < N; i++) {
    const normalizedScore = Number(((ranks[i] / maxRank) * 100).toFixed(1));
    pageRankById.set(validNodes[i].id, normalizedScore);
  }

  // 2. Deterministic Label Propagation Community Detection (weighted by PageRank + folder/tag affinity)
  let labels = validNodes.map((n, i) => i);
  const nodeOrder = Array.from({ length: N }, (_, i) => i).sort(
    (a, b) => ranks[b] - ranks[a] || validNodes[a].id.localeCompare(validNodes[b].id),
  );

  for (let step = 0; step < 12; step++) {
    let changed = false;
    for (const u of nodeOrder) {
      const neighbors = [...undirectedAdj[u]];
      if (!neighbors.length) continue;
      const scoreByLabel = new Map();
      const folderU = validNodes[u].folder || '根目录';
      const tagsU = new Set(validNodes[u].tags || []);

      for (const v of neighbors) {
        const lbl = labels[v];
        let weight = 1 + ranks[v] * 2.5;
        if ((validNodes[v].folder || '根目录') === folderU && folderU !== '根目录') weight += 0.45;
        for (const t of validNodes[v].tags || []) {
          if (tagsU.has(t)) weight += 0.25;
        }
        scoreByLabel.set(lbl, (scoreByLabel.get(lbl) || 0) + weight);
      }

      let bestLabel = labels[u];
      let bestScore = -1;
      for (const [lbl, sc] of scoreByLabel.entries()) {
        if (sc > bestScore || (Math.abs(sc - bestScore) < 1e-6 && lbl < bestLabel)) {
          bestScore = sc;
          bestLabel = lbl;
        }
      }
      if (bestLabel !== labels[u]) {
        labels[u] = bestLabel;
        changed = true;
      }
    }
    if (!changed) break;
  }

  // Group nodes by label and assign clean community IDs sorted by size desc
  const rawGroups = new Map();
  for (let i = 0; i < N; i++) {
    const lbl = labels[i];
    if (!rawGroups.has(lbl)) rawGroups.set(lbl, []);
    rawGroups.get(lbl).push(validNodes[i]);
  }
  const sortedGroups = [...rawGroups.values()].sort(
    (a, b) => b.length - a.length || (pageRankById.get(b[0].id) || 0) - (pageRankById.get(a[0].id) || 0),
  );

  const communities = [];
  const communityById = new Map();
  sortedGroups.forEach((groupNodes, idx) => {
    const sortedMembers = [...groupNodes].sort(
      (a, b) => (pageRankById.get(b.id) || 0) - (pageRankById.get(a.id) || 0) || String(a.title || '').localeCompare(String(b.title || ''), 'zh-CN'),
    );
    const leadNode = sortedMembers[0];
    const leadTitle = formatConciseGraphTitle(leadNode?.cleanTitle || leadNode?.title || leadNode?.label || `群落 ${idx + 1}`, 9);
    const communityId = `cluster-${idx + 1}`;
    const tone = COMMUNITY_TONES[idx % COMMUNITY_TONES.length];
    const label = groupNodes.length === 1 && leadNode?.orphan
      ? `孤岛 · ${leadTitle}`
      : `社区 ${idx + 1} · ${leadTitle}`;
    const record = {
      id: communityId,
      index: idx,
      label,
      leadNoteId: leadNode?.id || '',
      leadTitle,
      tone,
      count: groupNodes.length,
      nodeIds: sortedMembers.map(n => n.id),
    };
    communities.push(record);
    for (const member of sortedMembers) {
      communityById.set(member.id, {
        communityId,
        communityIndex: idx,
        communityLabel: label,
        communityTone: tone,
      });
    }
  });

  // 3. Identify cross-community bridge nodes
  const bridgeNodeIds = [];
  for (let i = 0; i < N; i++) {
    const myComm = communityById.get(validNodes[i].id)?.communityId;
    const neighborComms = new Set();
    for (const v of undirectedAdj[i]) {
      const nComm = communityById.get(validNodes[v].id)?.communityId;
      if (nComm && nComm !== myComm) neighborComms.add(nComm);
    }
    if (neighborComms.size > 0) {
      bridgeNodeIds.push(validNodes[i].id);
    }
  }

  // 4. Top PageRank Hubs
  const topHubs = [...validNodes]
    .filter(n => !n.ghost)
    .sort((a, b) => (pageRankById.get(b.id) || 0) - (pageRankById.get(a.id) || 0))
    .slice(0, 6)
    .map(n => ({
      id: n.id,
      title: stripNumericPrefix(n.cleanTitle || n.title || n.label || n.id),
      pageRank: pageRankById.get(n.id) || 0,
      communityId: communityById.get(n.id)?.communityId || '',
      communityLabel: communityById.get(n.id)?.communityLabel || '',
      isBridge: bridgeNodeIds.includes(n.id),
    }));

  return {
    pageRankById,
    communityById,
    communities,
    topHubs,
    bridgeNodeIds,
  };
}

/**
 * CANVAS-003: Note Cards on Whiteboard (Obsidian Canvas style note-card elements)
 */
export function createWhiteboardNoteCardElements(note = {}, existingElements = [], options = {}) {
  const cleanTitle = stripNumericPrefix(note.cleanTitle || note.title || note.name || '知识卡片') || '知识卡片';
  const rawSource = String(note.source || note.excerpt || '');
  const fm = parseFrontMatter(rawSource);
  const body = rawSource
    .slice(fm.bodyFrom)
    .replace(/```[\s\S]*?```/g, '')
    .replace(/^\s*#{1,6}\s+.+$/gm, '')
    .replace(/!?\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|([^\]]+))?\]\]/g, (_, target, alias) => alias || target)
    .replace(/[*>`~_]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  const excerpt = (body || fm.metadata?.summary || '点击卡片链接可直达对应 Markdown 笔记原文').slice(0, 76);
  const tagsLine = Array.isArray(note.tags) && note.tags.length
    ? note.tags.slice(0, 3).map(t => `#${t}`).join(' ')
    : (fm.metadata?.tags?.length ? fm.metadata.tags.slice(0, 3).map(t => `#${t}`).join(' ') : '#墨图卡片');

  const activeRects = (existingElements || []).filter(el => el && !el.isDeleted && el.type === 'rectangle');
  const idx = activeRects.length;
  const col = idx % 3;
  const row = Math.floor(idx / 3);
  const x = Number.isFinite(options.x) ? options.x : 60 + col * 290;
  const y = Number.isFinite(options.y) ? options.y : 60 + row * 185;
  const width = 260;
  const height = 148;
  const now = Date.now();
  const groupId = 'notecard-group-' + String(note.id || idx).replace(/[^A-Za-z0-9_-]/g, '') + '-' + (now % 100000);
  const rectId = 'notecard-rect-' + String(note.id || idx).replace(/[^A-Za-z0-9_-]/g, '') + '-' + (now % 100000);
  const textId = 'notecard-text-' + String(note.id || idx).replace(/[^A-Za-z0-9_-]/g, '') + '-' + (now % 100000);
  const wikiLink = `[[${cleanTitle}]]`;

  const wrapLine = (str, maxLen = 19) => {
    const lines = [];
    for (let i = 0; i < str.length; i += maxLen) {
      lines.push(str.slice(i, i + maxLen));
    }
    return lines.slice(0, 3).join('\n');
  };
  const cardText = [
    `📄 ${cleanTitle.slice(0, 18)}`,
    wrapLine(excerpt, 19),
    tagsLine,
  ].join('\n');

  const baseProps = {
    angle: 0,
    strokeStyle: 'solid',
    roughness: 0,
    opacity: 100,
    groupIds: [groupId],
    frameId: null,
    roundness: { type: 3 },
    seed: 1000 + idx * 17,
    version: 1,
    versionNonce: 2000 + idx * 31,
    isDeleted: false,
    boundElements: null,
    updated: now,
    link: wikiLink,
    locked: false,
  };

  const rectElement = {
    ...baseProps,
    id: rectId,
    type: 'rectangle',
    x,
    y,
    width,
    height,
    strokeColor: '#1d7268',
    backgroundColor: '#f0fdfa',
    fillStyle: 'solid',
    strokeWidth: 2,
  };

  const textElement = {
    ...baseProps,
    id: textId,
    type: 'text',
    x: x + 14,
    y: y + 14,
    width: width - 28,
    height: height - 28,
    strokeColor: '#1e293b',
    backgroundColor: 'transparent',
    fillStyle: 'solid',
    strokeWidth: 1,
    fontSize: 14,
    fontFamily: 1,
    text: cardText,
    textAlign: 'left',
    verticalAlign: 'top',
    containerId: null,
    originalText: cardText,
    lineHeight: 1.35,
  };

  const elements = [rectElement, textElement];

  // Optional: if connectFromElement is provided, add an arrow connecting them
  if (options.connectFromRect && Number.isFinite(options.connectFromRect.x)) {
    const prev = options.connectFromRect;
    const startX = prev.x + (prev.width || 260);
    const startY = prev.y + (prev.height || 148) / 2;
    const endX = x;
    const endY = y + height / 2;
    const dx = endX - startX;
    const dy = endY - startY;
    elements.push({
      ...baseProps,
      id: 'notecard-arrow-' + String(note.id || idx).replace(/[^A-Za-z0-9_-]/g, '') + '-' + idx + '-' + (now % 100000),
      type: 'arrow',
      groupIds: [],
      x: startX,
      y: startY,
      width: Math.abs(dx),
      height: Math.abs(dy),
      strokeColor: '#1d7268',
      backgroundColor: 'transparent',
      fillStyle: 'solid',
      strokeWidth: 2,
      points: [[0, 0], [dx, dy]],
      lastCommittedPoint: null,
      startBinding: null,
      endBinding: null,
      startArrowhead: null,
      endArrowhead: 'arrow',
    });
  }

  return {
    title: cleanTitle,
    link: wikiLink,
    rectElement,
    textElement,
    elements,
  };
}

export function extractWhiteboardNoteCards(elements = []) {
  const seen = new Set();
  const cards = [];
  for (const el of elements || []) {
    if (!el || el.isDeleted || typeof el.link !== 'string') continue;
    const match = /^\[\[([^\]|#]+)(?:#([^\]|]+))?(?:\|([^\]]+))?\]\]$/.exec(el.link.trim());
    if (!match) continue;
    const target = match[1].trim();
    const key = target.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    cards.push({
      target,
      heading: (match[2] || '').trim(),
      display: (match[3] || target).trim(),
      link: el.link.trim(),
      elementId: el.id,
    });
  }
  return cards;
}

/* ============================================================================
 * MAJOR-240 (2.4.0): Obsidian JSON Canvas (.canvas 1.0) Bidirectional Engine &
 * Knowledge Graph Subgraph / Path -> Spatial Whiteboard Synthesis
 * ========================================================================== */

const JSON_CANVAS_COLOR_MAP = {
  '1': { stroke: '#dc2626', bg: '#fef2f2' },
  '2': { stroke: '#ea580c', bg: '#fff7ed' },
  '3': { stroke: '#ca8a04', bg: '#fefce8' },
  '4': { stroke: '#16a34a', bg: '#f0fdf4' },
  '5': { stroke: '#0d9488', bg: '#f0fdfa' },
  '6': { stroke: '#7c3aed', bg: '#f5f3ff' },
};

/**
 * Convert an Obsidian JSON Canvas 1.0 object ({ nodes, edges }) into an Inkloom Excalidraw scene.
 */
export function convertJsonCanvasToWhiteboardScene(canvasInput = {}, vaultNotes = []) {
  const raw = typeof canvasInput === 'string' ? JSON.parse(canvasInput) : (canvasInput || {});
  if (!Array.isArray(raw.nodes)) {
    throw new Error('JSON Canvas 格式无效：缺少 nodes 数组');
  }
  const elements = [];
  const nodeBoxById = new Map();
  const now = Date.now();

  const noteByStem = new Map();
  for (const n of vaultNotes || []) {
    const clean = stripNumericPrefix(n?.cleanTitle || n?.title || n?.name || '').toLowerCase();
    if (clean) noteByStem.set(clean, n);
    const rel = String(n?.relativePath || n?.name || '').replace(/\\/g, '/').replace(/\.(md|markdown)$/i, '').toLowerCase();
    if (rel) noteByStem.set(rel, n);
  }

  raw.nodes.forEach((node, idx) => {
    if (!node || typeof node.id !== 'string' || !node.id) return;
    const safeId = node.id.replace(/[^A-Za-z0-9_-]/g, '') || `node-${idx}`;
    const x = Number.isFinite(node.x) ? Math.round(node.x) : idx * 300;
    const y = Number.isFinite(node.y) ? Math.round(node.y) : 60;
    const width = Number.isFinite(node.width) && node.width > 20 ? Math.round(node.width) : 260;
    const height = Number.isFinite(node.height) && node.height > 20 ? Math.round(node.height) : 148;
    nodeBoxById.set(node.id, { x, y, width, height });

    const palette = JSON_CANVAS_COLOR_MAP[String(node.color || '')] || {
      stroke: /^#[0-9a-f]{6}$/i.test(node.color || '') ? node.color : '#1d7268',
      bg: '#f0fdfa',
    };

    if (node.type === 'file' && node.file) {
      const cleanRel = String(node.file).replace(/\\/g, '/').replace(/\.(md|markdown)$/i, '').trim();
      const baseTitle = stripNumericPrefix(cleanRel.split('/').pop() || cleanRel) || '关联笔记';
      const matched = noteByStem.get(cleanRel.toLowerCase()) || noteByStem.get(baseTitle.toLowerCase());
      const card = createWhiteboardNoteCardElements(
        matched || { id: safeId, title: baseTitle, source: node.text || '' },
        elements,
        { x, y },
      );
      card.rectElement.id = `jc-rect-${safeId}`;
      card.rectElement.width = width;
      card.rectElement.height = height;
      card.rectElement.strokeColor = palette.stroke;
      card.rectElement.backgroundColor = palette.bg;
      card.textElement.id = `jc-text-${safeId}`;
      card.textElement.width = Math.max(40, width - 28);
      card.textElement.height = Math.max(24, height - 28);
      elements.push(card.rectElement, card.textElement);
      return;
    }

    const isGroup = node.type === 'group';
    const linkVal = node.type === 'link' && typeof node.url === 'string' && /^https?:\/\//i.test(node.url)
      ? node.url.trim()
      : null;
    const groupId = `jc-grp-${safeId}`;
    const baseProps = {
      angle: 0,
      strokeStyle: isGroup ? 'dashed' : 'solid',
      roughness: 0,
      opacity: 100,
      groupIds: [groupId],
      frameId: null,
      roundness: { type: 3 },
      seed: 3000 + idx * 19,
      version: 1,
      versionNonce: 4000 + idx * 29,
      isDeleted: false,
      boundElements: null,
      updated: now,
      link: linkVal,
      locked: false,
    };

    elements.push({
      ...baseProps,
      id: `jc-rect-${safeId}`,
      type: isGroup ? 'frame' : 'rectangle',
      x,
      y,
      width,
      height,
      strokeColor: isGroup ? '#64748b' : palette.stroke,
      backgroundColor: isGroup ? 'transparent' : palette.bg,
      fillStyle: 'solid',
      strokeWidth: isGroup ? 1 : 2,
    });

    const rawText = isGroup
      ? String(node.label || '分组区域')
      : node.type === 'link'
        ? `🔗 ${node.label || node.url || '外部链接'}`
        : String(node.text || node.label || '文本卡片');
    elements.push({
      ...baseProps,
      id: `jc-text-${safeId}`,
      type: 'text',
      x: x + 14,
      y: y + 14,
      width: Math.max(40, width - 28),
      height: Math.max(24, height - 28),
      strokeColor: '#1e293b',
      backgroundColor: 'transparent',
      fillStyle: 'solid',
      strokeWidth: 1,
      fontSize: 14,
      fontFamily: 1,
      text: rawText.slice(0, 500),
      textAlign: 'left',
      verticalAlign: 'top',
      containerId: null,
      originalText: rawText.slice(0, 500),
      lineHeight: 1.35,
    });
  });

  (raw.edges || []).forEach((edge, idx) => {
    if (!edge || !nodeBoxById.has(edge.fromNode) || !nodeBoxById.has(edge.toNode)) return;
    const fromBox = nodeBoxById.get(edge.fromNode);
    const toBox = nodeBoxById.get(edge.toNode);
    const safeEdgeId = String(edge.id || `edge-${idx}`).replace(/[^A-Za-z0-9_-]/g, '') || `edge-${idx}`;
    const startX = fromBox.x + fromBox.width;
    const startY = fromBox.y + Math.round(fromBox.height / 2);
    const endX = toBox.x;
    const endY = toBox.y + Math.round(toBox.height / 2);
    const dx = endX - startX;
    const dy = endY - startY;
    elements.push({
      id: `jc-edge-${safeEdgeId}-${idx}`,
      type: 'arrow',
      x: startX,
      y: startY,
      width: Math.abs(dx),
      height: Math.abs(dy),
      angle: 0,
      strokeColor: '#1d7268',
      backgroundColor: 'transparent',
      fillStyle: 'solid',
      strokeWidth: 2,
      strokeStyle: 'solid',
      roughness: 0,
      opacity: 100,
      groupIds: [],
      frameId: null,
      roundness: { type: 2 },
      seed: 5000 + idx * 23,
      version: 1,
      versionNonce: 6000 + idx * 37,
      isDeleted: false,
      boundElements: null,
      updated: now,
      link: null,
      locked: false,
      points: [[0, 0], [dx, dy]],
      lastCommittedPoint: null,
      startBinding: null,
      endBinding: null,
      startArrowhead: null,
      endArrowhead: 'arrow',
    });
  });

  return {
    type: 'excalidraw',
    version: 2,
    source: 'Inkloom',
    elements,
    appState: { viewBackgroundColor: '#ffffff', gridModeEnabled: false },
    files: {},
  };
}

/**
 * Export an Inkloom Excalidraw scene into Obsidian JSON Canvas 1.0 format ({ nodes, edges }).
 */
export function exportWhiteboardSceneToJsonCanvas(scene = {}) {
  const active = (scene?.elements || []).filter(el => el && !el.isDeleted);
  const textByGroup = new Map();
  for (const el of active) {
    if (el.type === 'text' && Array.isArray(el.groupIds) && el.groupIds[0]) {
      textByGroup.set(el.groupIds[0], el.text || '');
    }
  }

  const nodes = [];
  const consumedTextIds = new Set();

  for (const el of active) {
    if (el.type === 'rectangle' || el.type === 'frame' || el.type === 'diamond' || el.type === 'ellipse') {
      const grpId = Array.isArray(el.groupIds) && el.groupIds[0] ? el.groupIds[0] : '';
      let pairedText = grpId ? (textByGroup.get(grpId) || '') : '';
      if (!pairedText) {
        const insideText = active.find(
          t => t.type === 'text' && !consumedTextIds.has(t.id) &&
            t.x >= el.x - 10 && t.x <= el.x + (el.width || 200) &&
            t.y >= el.y - 10 && t.y <= el.y + (el.height || 120),
        );
        if (insideText) {
          pairedText = insideText.text || '';
          consumedTextIds.add(insideText.id);
        }
      } else {
        for (const t of active) {
          if (t.type === 'text' && Array.isArray(t.groupIds) && t.groupIds[0] === grpId) {
            consumedTextIds.add(t.id);
          }
        }
      }

      const x = Math.round(el.x || 0);
      const y = Math.round(el.y || 0);
      const width = Math.max(60, Math.round(el.width || 240));
      const height = Math.max(40, Math.round(el.height || 140));

      if (el.type === 'frame') {
        nodes.push({
          id: el.id,
          type: 'group',
          x,
          y,
          width,
          height,
          label: pairedText || '分组',
        });
      } else if (typeof el.link === 'string' && /^\[\[([^\]]+)\]\]$/.test(el.link.trim())) {
        const inner = el.link.trim().slice(2, -2).split('|')[0].split('#')[0].trim();
        nodes.push({
          id: el.id,
          type: 'file',
          file: inner.endsWith('.md') ? inner : `${inner}.md`,
          x,
          y,
          width,
          height,
          color: '5',
        });
      } else if (typeof el.link === 'string' && /^https?:\/\//i.test(el.link.trim())) {
        nodes.push({
          id: el.id,
          type: 'link',
          url: el.link.trim(),
          x,
          y,
          width,
          height,
        });
      } else {
        nodes.push({
          id: el.id,
          type: 'text',
          text: pairedText || '',
          x,
          y,
          width,
          height,
        });
      }
    }
  }

  for (const el of active) {
    if (el.type === 'text' && !consumedTextIds.has(el.id)) {
      nodes.push({
        id: el.id,
        type: 'text',
        text: el.text || '',
        x: Math.round(el.x || 0),
        y: Math.round(el.y || 0),
        width: Math.max(80, Math.round(el.width || 200)),
        height: Math.max(40, Math.round(el.height || 60)),
      });
    }
  }

  const edges = [];
  const candidateEdgeNodes = nodes.filter(n => n.type !== 'group');
  const poolNodes = candidateEdgeNodes.length ? candidateEdgeNodes : nodes;
  const findNearestNode = (px, py) => {
    let best = null;
    let bestDist = Infinity;
    for (const n of poolNodes) {
      const dx = Math.max(n.x - px, 0, px - (n.x + n.width));
      const dy = Math.max(n.y - py, 0, py - (n.y + n.height));
      const dist = Math.hypot(dx, dy);
      if (dist < bestDist) {
        bestDist = dist;
        best = n;
      }
    }
    return best;
  };

  for (const el of active) {
    if (el.type !== 'arrow' || !nodes.length) continue;
    const pts = Array.isArray(el.points) && el.points.length >= 2 ? el.points : [[0, 0], [el.width || 100, el.height || 0]];
    const startPt = pts[0];
    const endPt = pts[pts.length - 1];
    const sx = (el.x || 0) + startPt[0];
    const sy = (el.y || 0) + startPt[1];
    const ex = (el.x || 0) + endPt[0];
    const ey = (el.y || 0) + endPt[1];
    const fromNode = findNearestNode(sx, sy);
    const toNode = findNearestNode(ex, ey);
    if (fromNode && toNode && fromNode.id !== toNode.id) {
      edges.push({
        id: el.id,
        fromNode: fromNode.id,
        fromSide: 'right',
        toNode: toNode.id,
        toSide: 'left',
      });
    }
  }

  return {
    nodes,
    edges,
  };
}

/**
 * Synthesize an Excalidraw Whiteboard scene from a Knowledge Graph shortest path or community subgraph.
 */
export function buildWhiteboardSceneFromGraphSubgraph(nodes = [], edges = [], options = {}) {
  const pathResult = options.pathResult;
  const elements = [];
  const rectByNodeId = new Map();

  let selectedNodes = [];
  if (pathResult?.found && Array.isArray(pathResult.steps) && pathResult.steps.length > 0) {
    const nodeById = new Map((nodes || []).map(n => [n.id, n]));
    selectedNodes = pathResult.steps.map(st => nodeById.get(st.id) || { id: st.id, title: st.cleanTitle || st.title });
  } else {
    selectedNodes = (nodes || []).filter(n => n && !n.ghost).slice(0, options.maxNodes || 9);
  }

  let prevRect = null;
  selectedNodes.forEach((node, idx) => {
    const col = idx % 3;
    const row = Math.floor(idx / 3);
    const x = 60 + col * 310;
    const y = 60 + row * 200;
    const connectFrom = (pathResult?.found && prevRect) ? prevRect : null;
    const card = createWhiteboardNoteCardElements(node, elements, {
      x,
      y,
      connectFromRect: connectFrom,
    });
    rectByNodeId.set(node.id, card.rectElement);
    prevRect = card.rectElement;
    elements.push(...card.elements);
  });

  if (!pathResult?.found) {
    const now = Date.now();
    (edges || []).slice(0, 18).forEach((edge, idx) => {
      const fromRect = rectByNodeId.get(edge.source);
      const toRect = rectByNodeId.get(edge.target);
      if (!fromRect || !toRect || fromRect.id === toRect.id) return;
      const startX = fromRect.x + fromRect.width;
      const startY = fromRect.y + Math.round(fromRect.height / 2);
      const endX = toRect.x;
      const endY = toRect.y + Math.round(toRect.height / 2);
      const dx = endX - startX;
      const dy = endY - startY;
      elements.push({
        id: `subgraph-arrow-${idx}-${now % 100000}`,
        type: 'arrow',
        x: startX,
        y: startY,
        width: Math.abs(dx),
        height: Math.abs(dy),
        angle: 0,
        strokeColor: '#1d7268',
        backgroundColor: 'transparent',
        fillStyle: 'solid',
        strokeWidth: 2,
        strokeStyle: 'solid',
        roughness: 0,
        opacity: 100,
        groupIds: [],
        frameId: null,
        roundness: { type: 2 },
        seed: 7000 + idx * 13,
        version: 1,
        versionNonce: 8000 + idx * 29,
        isDeleted: false,
        boundElements: null,
        updated: now,
        link: null,
        locked: false,
        points: [[0, 0], [dx, dy]],
        lastCommittedPoint: null,
        startBinding: null,
        endBinding: null,
        startArrowhead: null,
        endArrowhead: 'arrow',
      });
    });
  }

  return {
    type: 'excalidraw',
    version: 2,
    source: 'Inkloom',
    elements,
    appState: { viewBackgroundColor: '#ffffff', gridModeEnabled: false },
    files: {},
    cardCount: selectedNodes.length,
  };
}
